import{_ as e,o as t,c as s,a2 as o}from"./chunks/framework.DaAAbehN.js";const u=JSON.parse('{"title":"第 8 课：文件操作 —— Codex 最基础的能力","description":"","frontmatter":{},"headers":[],"relativePath":"zh/modules/module-3/lesson-8.md","filePath":"zh/modules/module-3/lesson-8.md"}'),l={name:"zh/modules/module-3/lesson-8.md"};function n(i,a,d,p,h,r){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-8-课-文件操作-——-codex-最基础的能力" tabindex="-1">第 8 课：文件操作 —— Codex 最基础的能力 <a class="header-anchor" href="#第-8-课-文件操作-——-codex-最基础的能力" aria-label="Permalink to &quot;第 8 课：文件操作 —— Codex 最基础的能力&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：掌握用 Codex 进行文件读取、编辑、整理的基本方法<br> ⏱️ <strong>预计时长</strong>：25 分钟<br> 🎯 <strong>本节节奏</strong>：先演示 → 后讲解 → 再实操</p></blockquote><hr><h2 id="一、codex-能读取你电脑上的文件" tabindex="-1">一、Codex 能读取你电脑上的文件 <a class="header-anchor" href="#一、codex-能读取你电脑上的文件" aria-label="Permalink to &quot;一、Codex 能读取你电脑上的文件&quot;">​</a></h2><p>这是 Codex 最基础、也是最核心的能力之一。</p><h3 id="_1-1-拖拽文件进入对话" tabindex="-1">1.1 拖拽文件进入对话 <a class="header-anchor" href="#_1-1-拖拽文件进入对话" aria-label="Permalink to &quot;1.1 拖拽文件进入对话&quot;">​</a></h3><p>打开 Codex，直接把文件拖进对话框或工作区：</p><ul><li><strong>文本文件</strong>（.txt, .md, .csv）→ Codex 可以直接阅读内容</li><li><strong>代码文件</strong>（.py, .js, .html）→ Codex 可以分析并修改</li><li><strong>图片文件</strong>（.jpg, .png）→ Codex 可以识别图片中的内容</li><li><strong>PDF 文件</strong> → Codex 可以提取文字并总结</li></ul><h3 id="_1-2-让-codex-读取文件夹" tabindex="-1">1.2 让 Codex 读取文件夹 <a class="header-anchor" href="#_1-2-让-codex-读取文件夹" aria-label="Permalink to &quot;1.2 让 Codex 读取文件夹&quot;">​</a></h3><p>除了单个文件，你还可以让 Codex 读取整个文件夹：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看看这个文件夹里有什么文件</span></span></code></pre></div><p>Codex 会列出所有文件名、大小、修改日期等信息。</p><hr><h2 id="二、实操一-让-codex-帮你整理文档" tabindex="-1">二、实操一：让 Codex 帮你整理文档 <a class="header-anchor" href="#二、实操一-让-codex-帮你整理文档" aria-label="Permalink to &quot;二、实操一：让 Codex 帮你整理文档&quot;">​</a></h2><h3 id="场景" tabindex="-1">场景 <a class="header-anchor" href="#场景" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>你有一个&quot;杂乱的文档&quot;文件夹，里面混放着：</p><ul><li>Word 文档 (.docx)</li><li>PDF 文件</li><li>Excel 表格 (.xlsx)</li><li>文本文件 (.txt)</li></ul><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>在 Codex 中打开该文件夹作为工作区</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我整理这个文件夹，按文件类型创建子文件夹，把同类文件移进去</span></span></code></pre></div></li><li>Codex 会： <ul><li>扫描所有文件</li><li>创建 <code>documents/</code>, <code>pdfs/</code>, <code>spreadsheets/</code>, <code>text-files/</code> 等子文件夹</li><li>将文件移动到对应位置</li></ul></li></ol><h3 id="进阶指令" tabindex="-1">进阶指令 <a class="header-anchor" href="#进阶指令" aria-label="Permalink to &quot;进阶指令&quot;">​</a></h3><p>如果你想更精细地控制：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个文件夹里的所有 PDF 文件移到名为&quot;报告&quot;的子文件夹里</span></span></code></pre></div><p>或者：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>找出所有超过 10MB 的文件，把它们移到&quot;大文件&quot;文件夹</span></span></code></pre></div><hr><h2 id="三、实操二-批量重命名文件" tabindex="-1">三、实操二：批量重命名文件 <a class="header-anchor" href="#三、实操二-批量重命名文件" aria-label="Permalink to &quot;三、实操二：批量重命名文件&quot;">​</a></h2><h3 id="场景-1" tabindex="-1">场景 <a class="header-anchor" href="#场景-1" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>你有一批照片，文件名是 <code>IMG_001.jpg</code>, <code>IMG_002.jpg</code>... 你想改成更有意义的名字。</p><h3 id="操作步骤-1" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>打开照片文件夹作为工作区</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这些照片的文件名改成&quot;旅行-序号.jpg&quot;的格式，比如&quot;旅行-001.jpg&quot;</span></span></code></pre></div></li><li>Codex 会执行批量重命名</li></ol><h3 id="更多示例" tabindex="-1">更多示例 <a class="header-anchor" href="#更多示例" aria-label="Permalink to &quot;更多示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的指令</th><th>Codex 会做什么</th></tr></thead><tbody><tr><td>&quot;把所有 .JPG 改成 .jpg&quot;</td><td>统一小写扩展名</td></tr><tr><td>&quot;在文件名前面加上日期前缀 20260722&quot;</td><td>添加日期前缀</td></tr><tr><td>&quot;去掉所有文件名中的空格&quot;</td><td>清理文件名</td></tr></tbody></table><hr><h2 id="四、实操三-分析文件夹空间占用" tabindex="-1">四、实操三：分析文件夹空间占用 <a class="header-anchor" href="#四、实操三-分析文件夹空间占用" aria-label="Permalink to &quot;四、实操三：分析文件夹空间占用&quot;">​</a></h2><h3 id="场景-2" tabindex="-1">场景 <a class="header-anchor" href="#场景-2" aria-label="Permalink to &quot;场景&quot;">​</a></h3><p>你的硬盘快满了，想知道是什么占用了空间。</p><h3 id="操作步骤-2" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-2" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>打开目标文件夹（比如整个&quot;下载&quot;文件夹）</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我分析一下这个文件夹的空间占用情况，列出最大的 10 个文件</span></span></code></pre></div></li><li>Codex 会生成类似这样的报告：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📊 文件夹空间分析报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总大小：4.2 GB</span></span>
<span class="line"><span>文件总数：328</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Top 10 最大文件：</span></span>
<span class="line"><span>1. video_backup.mp4 - 1.2 GB</span></span>
<span class="line"><span>2. database_dump.sql - 850 MB</span></span>
<span class="line"><span>3. project_archive.zip - 620 MB</span></span>
<span class="line"><span>...</span></span></code></pre></div><hr><h2 id="五、codex-能编辑文件吗" tabindex="-1">五、Codex 能编辑文件吗？ <a class="header-anchor" href="#五、codex-能编辑文件吗" aria-label="Permalink to &quot;五、Codex 能编辑文件吗？&quot;">​</a></h2><p><strong>可以！</strong> 而且这是它非常强大的一个能力。</p><h3 id="示例-修改文本文件" tabindex="-1">示例：修改文本文件 <a class="header-anchor" href="#示例-修改文本文件" aria-label="Permalink to &quot;示例：修改文本文件&quot;">​</a></h3><p>假设你有一个 <code>notes.txt</code> 文件，内容是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>待办事项：</span></span>
<span class="line"><span>1. 买牛奶</span></span>
<span class="line"><span>2. 交房租</span></span>
<span class="line"><span>3. 预约牙医</span></span></code></pre></div><p>你可以告诉 Codex：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我把这份待办事项加上一项：&quot;预约理发&quot;，放在最后</span></span></code></pre></div><p>Codex 会直接修改原文件，加上新的待办事项。</p><h3 id="示例-格式化数据" tabindex="-1">示例：格式化数据 <a class="header-anchor" href="#示例-格式化数据" aria-label="Permalink to &quot;示例：格式化数据&quot;">​</a></h3><p>假设你有一个 CSV 文件，数据格式混乱。你可以说：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我整理这个 CSV 文件，确保每一列都有标题，去除空行，统一日期格式为 YYYY-MM-DD</span></span></code></pre></div><p>Codex 会读取文件、修改内容、保存结果。</p><hr><h2 id="六、本节实操任务清单" tabindex="-1">六、本节实操任务清单 <a class="header-anchor" href="#六、本节实操任务清单" aria-label="Permalink to &quot;六、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 创建一个测试文件夹，放入不同类型的文件（.txt, .pdf, .jpg, .xlsx）</li><li>[ ] 让 Codex 统计文件夹中的文件数量和类型分布</li><li>[ ] 让 Codex 按文件类型自动分类到不同子文件夹</li><li>[ ] 让 Codex 批量重命名一批文件</li><li>[ ] 让 Codex 分析文件夹的空间占用情况</li></ul><hr><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>读取文件</td><td>支持文本、代码、图片、PDF 等多种格式</td></tr><tr><td>读取文件夹</td><td>列出文件树、统计信息</td></tr><tr><td>编辑文件</td><td>直接修改文件内容</td></tr><tr><td>批量操作</td><td>重命名、移动、分类、格式化</td></tr><tr><td>空间分析</td><td>查看文件大小和占用情况</td></tr></tbody></table><hr><h2 id="八、下一步" tabindex="-1">八、下一步 <a class="header-anchor" href="#八、下一步" aria-label="Permalink to &quot;八、下一步&quot;">​</a></h2><p><a href="./lesson-9.html">→ 第 9 课：自然语言驱动</a></p>`,62)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
